import{_ as e,o as s,c as o,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const P=JSON.parse('{"title":"Ceph Performance Meeting 2018-10-25","description":"","frontmatter":{"title":"Ceph Performance Meeting 2018-10-25","date":"2018-10-25T00:00:00.000Z","updated":"2018-10-26T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","RocksDB","OMAP"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Performance_Meeting_2018-10-25.md","filePath":"posts/2018/Ceph_Performance_Meeting_2018-10-25.md","lastUpdated":1780459816000}'),r={name:"posts/2018/Ceph_Performance_Meeting_2018-10-25.md"};function i(l,t,a,p,g,c){return s(),o("div",null,[...t[0]||(t[0]=[n("<p>在 2018-10-25 举行的 Ceph 性能会议上，与会人员讨论了多个关键议题，包括 PR 审批、Numa 架构优化、OMAP 性能测试和 RocksDB 数据库优化。以下是对会议内容的详细总结：</p><p><strong>一、PR 审批及后续行动</strong></p><ul><li><strong>Radek 的 PR</strong>： 讨论了 Radek 提交的多个 PR，包括缓冲区历史工作、性能测试、数据依赖性分析等。会议决定将大型 PR 分解成更小的部分进行审查，并讨论了简化热点路径的复杂性方案。</li><li><strong>其他 PR</strong>： 讨论了其他 PR 的进展，包括 gzip 压缩、stack string stream、延迟延迟、OMAP 测试等。</li><li><strong>遗留问题</strong>： 讨论了遗留问题的处理，包括 attic、slapped allocators、临时内存池计数器等。</li></ul><p><strong>二、Numa 架构优化</strong></p><ul><li>讨论了 Numa 架构优化方案，包括 pinning Numa 节点内存、OSD 跨多个 Numa 节点分布等。</li><li>认识到 Numa 架构优化是一个复杂的问题，需要谨慎处理，并确保不会降低性能。</li></ul><p><strong>三、OMAP 性能测试</strong></p><ul><li>讨论了 OMAP 性能测试结果，包括单操作延迟、DB 大小等。</li><li>认识到 RocksDB 数据库的 DB 大小设置需要优化，以确保性能。</li><li>讨论了 OMAP 操作批处理的可能性，以提高性能。</li></ul><p><strong>四、RocksDB 数据库优化</strong></p><ul><li>讨论了 RocksDB 数据库的优化方案，包括自动调整级别大小、压缩和写放大等。</li><li>认识到 RocksDB 的级别大小设置需要优化，以确保性能。</li></ul><p><strong>五、其他</strong></p><ul><li>讨论了 Rados Bench 的优化，以及是否将重点放在 OMAP 性能测试上。</li><li>讨论了 RocksDB 的 tombstones 问题。</li></ul><p><strong>行动计划</strong></p><ul><li><strong>Radek</strong>：将大型 PR 分解成更小的部分进行审查，并讨论简化热点路径的复杂性方案。</li><li><strong>Neha 和 Adam</strong>：调查 stack string stream 中的崩溃问题。</li><li><strong>Sage</strong>：调查 clean PG set 仍然刷新的问题。</li><li><strong>Nick</strong>：调查 RocksDB 的 DB 大小设置问题，并尝试优化级别大小。</li><li><strong>Josh 和 Matt</strong>：讨论 OMAP 操作批处理的可能性。</li><li><strong>Eric</strong>：调查 RocksDB 的 tombstones 问题。</li></ul><p>本次会议讨论了 Ceph 项目的多个重要议题，并制定了相应的行动计划。会议强调了 PR 审批、Numa 架构优化、OMAP 性能测试和 RocksDB 数据库优化的重要性。</p>",14)])])}const m=e(r,[["render",i]]);export{P as __pageData,m as default};
